{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "Insufficient torque authority (tau_ratio=0.237 vs reference 0.995) prevents generating enough joint torque to arrest forward falls and propel the body forward.",
      "evidence": [
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "baseline.torque_authority",
        "baseline.saturation_frac",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_knee",
        "baseline.peak_tau_over_limit_ankle"
      ],
      "competing": [
        "Torque is sufficient but misallocated across joints or phases; the controller's timing/placement parameters need tuning instead."
      ]
    },
    {
      "id": "H2",
      "mechanism": "Controller frequency (1.55 Hz) is 3.14x the pendulum frequency (0.495 Hz), causing overly rapid, small steps (step_freq=5.74 Hz, step_length=0.02 L) that cannot arrest forward momentum.",
      "evidence": [
        "baseline.controller_freq_hz",
        "baseline.pendulum_freq_hz",
        "baseline.controller_freq_ratio",
        "baseline.step_freq_hz",
        "baseline.step_length_over_leg",
        "baseline.froude"
      ],
      "competing": [
        "High step frequency is a symptom of forward falling (desperate catch-up steps), not the root cause; fixing torque or foot placement would naturally lower step frequency."
      ]
    },
    {
      "id": "H3",
      "mechanism": "Foot placement feedback gains (fp_kd, fp_kv) are zero at start; without them, the swing foot lands behind the torso (touchdown_foot_ahead_mean=-0.26 L) and far behind the capture point (capture_margin_mean=-0.46 L), failing to arrest forward falls.",
      "evidence": [
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.touchdown_foot_ahead_over_leg_last",
        "baseline.capture_margin_over_leg_mean",
        "baseline.capture_margin_over_leg_min",
        "baseline.capture_margin_over_leg_last",
        "baseline.forward_fall_frac"
      ],
      "competing": [
        "Placement feedback cannot compensate for insufficient torque or wrong timing; the foot cannot be placed far enough forward if the leg lacks torque to swing it there quickly."
      ]
    },
    {
      "id": "H3",
      "mechanism": "The controller was tuned for a reference body with shorter legs (L=0.6 vs 1.012), longer relative feet (foot_to_leg=0.267 vs 0.140), heavier torso fraction (0.488 vs 0.263), and higher torque authority (tau_ratio=0.995 vs 0.237). Dynamic similarity transfer may rescale frequency, gains, and ramp to match the new morphology.",
      "evidence": [
        "creature.features.L",
        "creature.reference.features.L",
        "creature.features.foot_to_leg",
        "creature.reference.features.foot_to_leg",
        "creature.features.torso_frac",
        "creature.reference.features.torso_frac",
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio"
      ],
      "competing": [
        "Morphology differences are too large for simple rescaling; the controller structure itself (phase-based with fixed subspaces) may be inadequate for this body."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "torque_x1_5",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "similarity",
      "hypothesis": "H3",
      "expect": "improves"
    },
    {
      "probe_id": "opt_placement",
      "hypothesis": "H3",
      "expect": "improves"
    }
  ]
}

